const cfg = $('Clinic Config').first().json;
const body = $('Webhook').first().json.body;
const args = body.args || {};

// Window: now until +7 days. If Retell passed a parseable preferred_date,
// center a 3-day window on it instead.
let start = new Date();
let end = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

if (args.preferred_date) {
  const parsed = new Date(args.preferred_date);
  if (!isNaN(parsed) && parsed > new Date()) {
    start = parsed;
    end = new Date(parsed.getTime() + 3 * 24 * 60 * 60 * 1000);
  }
  // Natural language like "next Tuesday" won't parse; we silently fall back
  // to the default window, which is fine: the agent offers what exists.
}

return [{
  json: {
    startMs: start.getTime(),
    endMs: end.getTime(),
    calendarId: cfg.calendar_id,
    tz: cfg.clinic_tz,
  }
}];

const data = $json;
const tz = $('Prepare Range').first().json.tz;

// Collect ISO slots across all date keys, skipping metadata keys
const all = [];
for (const key of Object.keys(data)) {
  if (data[key] && Array.isArray(data[key].slots)) {
    all.push(...data[key].slots);
  }
}
all.sort();
const picked = all.slice(0, 5);

if (picked.length === 0) {
  return [{ json: {
    response: "I don't see any open times in the next few days. The clinic will text you some options.",
    slots: []
  }}];
}

const fmt = new Intl.DateTimeFormat('en-US', {
  weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit', timeZone: tz,
});
const spoken = picked.map(iso => fmt.format(new Date(iso)));

return [{ json: {
  response: "Available times: " + spoken.join(", ") + ". Would any of those work?",
  slots: picked
}}];
